import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [journeyStarted, setJourneyStarted] = useState(false);
  const [learningStarted, setLearningStarted] = useState(false);
  const [currentDay, setCurrentDay] = useState(1);
  const [completedTasks, setCompletedTasks] = useState({});

  const timeline = localStorage.getItem("timeline") || "3 months";

  let totalDays = 90;
  if (timeline.includes("month")) totalDays = parseInt(timeline) * 30;
  else if (timeline.includes("year")) totalDays = parseInt(timeline) * 365;

  // ✅ LOAD STATE
  useEffect(() => {
    const newDomain = name?.toLowerCase();
    const savedDomain = localStorage.getItem("selectedDomain");

    if (newDomain && savedDomain !== newDomain) {
      localStorage.setItem("selectedDomain", newDomain);

      localStorage.setItem("journeyStarted", "false");
      localStorage.setItem("learningStarted", "false");
      localStorage.setItem("currentDay", "1");
      localStorage.removeItem("roadmapPlan");
      localStorage.removeItem("completedTasks");

      setJourneyStarted(false);
      setLearningStarted(false);
      setCurrentDay(1);
      setCompletedTasks({});
    } else {
      setDomain(newDomain || savedDomain);
      setJourneyStarted(localStorage.getItem("journeyStarted") === "true");
      setLearningStarted(localStorage.getItem("learningStarted") === "true");
      setCurrentDay(parseInt(localStorage.getItem("currentDay") || "1"));

      const savedTasks = JSON.parse(localStorage.getItem("completedTasks") || "{}");
      setCompletedTasks(savedTasks);
    }

    if (!newDomain && savedDomain) {
      setDomain(savedDomain);
    }
  }, [name]);

  // 🔥 DOMAIN TOPICS
  const topicMap = {
    "web-development": [
      ["HTML"], ["CSS"], ["Flexbox"], ["JavaScript"], ["DOM"],
      ["React"], ["Hooks"], ["API"], ["Node.js"], ["MongoDB"], ["Project"]
    ],
    "ai-and-ml": [
      ["Python"], ["NumPy"], ["Pandas"], ["Visualization"],
      ["ML Basics"], ["Regression"], ["Deep Learning"], ["Project"]
    ]
  };

  const topics = topicMap[domain] || [["Basics"]];

  // 🔥 PLAN GENERATION
  const generatePlan = () => {
    const plan = [];
    const flatTopics = topics.flat();
    let index = 0;

    for (let day = 1; day <= totalDays; day++) {
      const daily = [];
      const count = 3 + (day % 2);

      for (let i = 0; i < count; i++) {
        if (index < flatTopics.length) {
          daily.push(flatTopics[index]);
          index++;
        }
      }

      if (daily.length === 0) daily.push("Revision / Practice");

      plan.push(daily);
    }

    return plan;
  };

  useEffect(() => {
    if (!localStorage.getItem("roadmapPlan") && domain) {
      const plan = generatePlan();
      localStorage.setItem("roadmapPlan", JSON.stringify(plan));
    }
  }, [domain]);

  const roadmapPlan = JSON.parse(localStorage.getItem("roadmapPlan") || "[]");

  // ✅ TOGGLE TASK PER DAY
  const toggleTask = (task) => {
    const dayTasks = completedTasks[currentDay] || [];

    let updatedDayTasks;

    if (dayTasks.includes(task)) {
      updatedDayTasks = dayTasks.filter(t => t !== task);
    } else {
      updatedDayTasks = [...dayTasks, task];
    }

    const updated = {
      ...completedTasks,
      [currentDay]: updatedDayTasks
    };

    setCompletedTasks(updated);
    localStorage.setItem("completedTasks", JSON.stringify(updated));
  };

  // ✅ REAL PROGRESS
  const totalTasks = roadmapPlan.flat().length;

  const completedCount = Object.values(completedTasks)
    .flat()
    .length;

  const progress = totalTasks
    ? (completedCount / totalTasks) * 100
    : 0;

  // ✅ AUTO NEXT DAY (FIXED)
  useEffect(() => {
    const todayTasks = roadmapPlan[currentDay - 1] || [];
    const completedToday = completedTasks[currentDay] || [];

    const allDone =
      todayTasks.length > 0 &&
      todayTasks.every(task => completedToday.includes(task));

    if (allDone) {
      const nextDay = currentDay + 1;
      setCurrentDay(nextDay);
      localStorage.setItem("currentDay", nextDay.toString());
    }
  }, [completedTasks, currentDay]);

  const handleStartJourney = () => {
    localStorage.setItem("journeyStarted", "true");
    setJourneyStarted(true);
  };

  const handleStartToday = () => {
    localStorage.setItem("learningStarted", "true");
    setLearningStarted(true);
  };

  const visibleDays = [currentDay - 1, currentDay, currentDay + 1].filter(d => d > 0);

  return (
    <div className="space-y-8">
      <Card title="Learning Roadmap">

        {/* DOMAIN HEADER */}
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold capitalize">
            🚀 {domain?.replaceAll("-", " ")} Roadmap
          </h2>
          <span className="text-sm text-gray-400">{timeline}</span>
        </div>

        {/* START JOURNEY */}
        {!journeyStarted && (
          <div className="text-center p-8">
            <h2 className="text-2xl font-bold mb-2">
              Start Your Learning Journey 🚀
            </h2>
            <button
              onClick={handleStartJourney}
              className="px-6 py-3 bg-gradient-to-r from-green-400 to-blue-500 text-white rounded-xl"
            >
              Start Journey
            </button>
          </div>
        )}

        {/* START TODAY */}
        {journeyStarted && !learningStarted && (
          <div className="text-center">
            <button
              onClick={handleStartToday}
              className="px-6 py-3 bg-teal-600 text-white rounded-xl"
            >
              Start From Today 📅
            </button>
          </div>
        )}

        {/* MAIN UI */}
        {learningStarted && (
          <>
            {/* HEADER */}
            <div className="flex items-center justify-between bg-slate-800 p-4 rounded-xl">
              <div>
                <h2 className="text-xl font-bold">Day {currentDay}</h2>
                <p className="text-sm text-gray-400">
                  {totalDays - currentDay} days remaining
                </p>
              </div>

              <div className="text-right">
                <p className="text-sm text-gray-400">Progress</p>
                <p className="font-semibold">{Math.floor(progress)}%</p>
              </div>
            </div>

            {/* PROGRESS BAR */}
            <div className="mt-4">
              <div className="w-full bg-slate-700 h-3 rounded-full">
                <div
                  className="h-3 rounded-full"
                  style={{
                    width: `${progress}%`,
                    background: "linear-gradient(90deg, #22c55e, #4f46e5)",
                  }}
                />
              </div>
            </div>

            {/* SUMMARY */}
            <div className="grid md:grid-cols-3 gap-4 mt-6">
              <div className="p-4 bg-slate-800 rounded-xl">
                <p className="text-gray-400 text-sm">Tasks Today</p>
                <h3 className="text-xl font-bold">
                  {(roadmapPlan[currentDay - 1] || []).length}
                </h3>
              </div>

              <div className="p-4 bg-slate-800 rounded-xl">
                <p className="text-gray-400 text-sm">Completed</p>
                <h3 className="text-xl font-bold">{completedCount}</h3>
              </div>

              <div className="p-4 bg-slate-800 rounded-xl">
                <p className="text-gray-400 text-sm">Domain</p>
                <h3 className="text-xl font-bold capitalize">{domain}</h3>
              </div>
            </div>

            {/* MULTI-DAY VIEW */}
            <div className="space-y-6 mt-6">
              {visibleDays.map(day => (
                <div key={day} className="p-4 bg-slate-800 rounded-xl">
                  <h3 className="font-semibold mb-3">
                    📅 Day {day} {day === currentDay && "(Today)"}
                  </h3>

                  <div className="grid md:grid-cols-2 gap-3">
                    {(roadmapPlan[day - 1] || []).map((task, i) => {
                      const isDone = completedTasks[day]?.includes(task);

                      return (
                        <div
                          key={i}
                          className={`p-3 rounded-lg border ${
                            isDone
                              ? "bg-green-900 border-green-500"
                              : "bg-slate-700 border-slate-600"
                          }`}
                        >
                          <label className="flex items-center gap-2">
                            <input
                              type="checkbox"
                              checked={isDone || false}
                              onChange={() => {
                                if (day === currentDay) toggleTask(task);
                              }}
                            />

                            <span className={isDone ? "line-through text-gray-400" : ""}>
                              {task}
                            </span>
                          </label>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            {/* BUTTON */}
            <Link to="/tasks">
              <button className="mt-6 px-6 py-3 bg-teal-500 text-white rounded-xl">
                Go to Tasks →
              </button>
            </Link>
          </>
        )}

      </Card>
